class Shape:
    def __init__(self):
        self.sides = 0

    def getArea(self):
        pass

# 矩形属于形状，但有特殊的属性 高度 和 宽度
class Rectangle(Shape):  # 继承自父类Shape
    # initializer
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.sides = 4

    # 矩形计算面积的实现
    def getArea(self):
        return (self.width * self.height)

# 圆形属于形状，并有特殊的属性 半径 radius
class Circle(Shape):  # 继承自父类Shape
    # 初始化函数
    def __init__(self, radius):
        self.radius = radius
        self.sides = 0

    # 计算圆形面积
    def getArea(self):
        return (self.radius * self.radius * 3.142)

class Shape:
    def __init__(self):  # 初始化函数默认sides 为 0
        self.sides = 0

    def getArea(self):
        pass


class Rectangle(Shape):  # 继承自Shape
    # 初始化函数
    def __init__(self, width=0, height=0):
        self.width = width
        self.height = height
        self.sides = 4

    # 计算矩形面积
    def getArea(self):
        return (self.width * self.height)


class Circle(Shape):  # 继承自Shape
    # 初始化函数
    def __init__(self, radius=0):
        self.radius = radius

    # 计算圆形面积
    def getArea(self):
        return (self.radius * self.radius * 3.142)


shapes = [Rectangle(6, 10), Circle(7)]
print("Area of rectangle is:", str(shapes[0].getArea()))
print("Area of circle is:", str(shapes[1].getArea()))
